// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.system.handlerimport timber.log.Timberimport android.app.NotificationChannelimport android.app.NotificationManagerimport android.content.Contextimport android.content.Intentimport android.os.Buildimport android.provider.AlarmClockimport androidx.core.app.NotificationCompatimport androidx.core.app.NotificationManagerCompat/** * NOUS — Notify Services (Module 10 v2 — Step 10.8). * * Three service interfaces for time/notification operations: *  - [AlarmClockService] — wraps `AlarmClock.ACTION_SET_ALARM` intents *  - [TimerService] — wraps `AlarmClock.ACTION_SET_TIMER` intents *  - [NotificationService] — wraps `NotificationManager` for posting/canceling * * ## Why interfaces? * * Same pattern as previous steps — thin wrappers for testability. Android's * `AlarmClock` is intent-based (no direct API), `NotificationManager` is a * concrete final class requiring a `Context`. */// ──────────────────────────────────────────────────────────────────────────// Alarm clock service// ──────────────────────────────────────────────────────────────────────────/** * Wraps `AlarmClock.ACTION_SET_ALARM` intent for [AlarmHandler]. */interface AlarmClockService {    /**     * Set an alarm.     *     * @param hour 0-23     * @param minute 0-59     * @param label optional label (e.g., "Wake up")     * @param daysOfWeek repeating days (empty = one-time). Days are     *                   `Calendar.SUNDAY` (1) through `Calendar.SATURDAY` (7).     * @return true if an alarm app was available to handle the intent.     */    fun setAlarm(hour: Int, minute: Int, label: String?, daysOfWeek: IntArray): Boolean    /**     * Open the system alarm list.     *     * @return true if the alarm app launched.     */    fun showAlarms(): Boolean}/** * Android [AlarmClockService] backed by `AlarmClock` intents. */class AndroidAlarmClockService(    private val context: Context,) : AlarmClockService {    override fun setAlarm(hour: Int, minute: Int, label: String?, daysOfWeek: IntArray): Boolean {        return try {            val intent = Intent(AlarmClock.ACTION_SET_ALARM).apply {                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)                putExtra(AlarmClock.EXTRA_HOUR, hour)                putExtra(AlarmClock.EXTRA_MINUTES, minute)                putExtra(AlarmClock.EXTRA_SKIP_UI, false)                if (!label.isNullOrBlank()) {                    putExtra(AlarmClock.EXTRA_MESSAGE, label)                }                if (daysOfWeek.isNotEmpty()) {                    putExtra(AlarmClock.EXTRA_DAYS, daysOfWeek)                }            }            context.startActivity(intent)            true        } catch (e: android.content.ActivityNotFoundException) {            Timber.tag("AndroidAlarmClockService").w("No alarm app installed", e)            throw e  // re-throw — handler maps to Hardware.Unsupported        } catch (t: Throwable) {            Timber.tag("AndroidAlarmClockService").w("setAlarm failed", t)            false        }    }    override fun showAlarms(): Boolean = try {        val intent = Intent(AlarmClock.ACTION_SHOW_ALARMS)            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        context.startActivity(intent)        true    } catch (t: Throwable) {        Timber.tag("AndroidAlarmClockService").w("showAlarms failed", t)        false    }}// ──────────────────────────────────────────────────────────────────────────// Timer service// ──────────────────────────────────────────────────────────────────────────/** * Wraps `AlarmClock.ACTION_SET_TIMER` intent for [TimerHandler]. */interface TimerService {    /**     * Set a countdown timer.     *     * @param durationSeconds timer length (e.g., 300 = 5 minutes)     * @param label optional label     * @param skipUi if true, don't show the timer app UI (just start the timer)     * @return true if a timer app handled the intent.     */    fun setTimer(durationSeconds: Long, label: String?, skipUi: Boolean = false): Boolean    /**     * Open the system timer list.     */    fun showTimers(): Boolean}/** * Android [TimerService] backed by `AlarmClock.ACTION_SET_TIMER`. */class AndroidTimerService(    private val context: Context,) : TimerService {    override fun setTimer(durationSeconds: Long, label: String?, skipUi: Boolean): Boolean {        return try {            val intent = Intent(AlarmClock.ACTION_SET_TIMER).apply {                addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)                putExtra(AlarmClock.EXTRA_LENGTH, durationSeconds)                putExtra(AlarmClock.EXTRA_SKIP_UI, skipUi)                if (!label.isNullOrBlank()) {                    putExtra(AlarmClock.EXTRA_MESSAGE, label)                }            }            context.startActivity(intent)            true        } catch (e: android.content.ActivityNotFoundException) {            Timber.tag("AndroidTimerService").w("No timer app installed", e)            throw e        } catch (t: Throwable) {            Timber.tag("AndroidTimerService").w("setTimer failed", t)            false        }    }    override fun showTimers(): Boolean = try {        // ACTION_SHOW_TIMERS is API 19+ but not in the public constant — use the string literal.        val intent = Intent("android.intent.action.SHOW_TIMERS")            .addFlags(Intent.FLAG_ACTIVITY_NEW_TASK)        context.startActivity(intent)        true    } catch (t: Throwable) {        Timber.tag("AndroidTimerService").w("showTimers failed", t)        false    }}// ──────────────────────────────────────────────────────────────────────────// Notification service// ──────────────────────────────────────────────────────────────────────────/** * Wraps [NotificationManager] for [NotificationHandler]. * * ## Channel idempotency * * On Android 8+ (Oreo), every notification requires a channel. Creating * a channel with the same ID twice is a no-op (the second call is silently * ignored) — but we still check `getNotificationChannel` first to avoid * the call + log spam. * * ## POST_NOTIFICATIONS permission (API 33+) * * Android 13 (Tiramisu) requires `POST_NOTIFICATIONS` runtime permission * to post notifications. Without it, `notify()` silently fails (no * exception). The handler should check this permission before calling. */interface NotificationService {    /**     * Ensure a notification channel exists (idempotent — no-op if already created).     *     * @param channelId unique channel ID     * @param name user-visible name ("NOUS Alerts")     * @param description channel description     * @param importance NotificationManager.IMPORTANCE_* constant     */    fun ensureChannel(channelId: String, name: String, description: String, importance: Int)    /** True if [channelId] channel exists. */    fun channelExists(channelId: String): Boolean    /**     * Post a notification.     *     * @param id notification ID (for later cancel)     * @param channelId channel ID (must exist via [ensureChannel])     * @param title notification title     * @param text notification body     * @param smallIconResId icon resource (defaults to android.R.drawable.ic_dialog_info)     * @return true if posted successfully.     */    fun postNotification(        id: Int,        channelId: String,        title: String,        text: String,        smallIconResId: Int = android.R.drawable.ic_dialog_info,    ): Boolean    /** Cancel a previously-posted notification by ID. */    fun cancelNotification(id: Int)    /** Cancel all NOUS notifications. */    fun cancelAll()    /** True if the app has POST_NOTIFICATIONS permission (API 33+) or pre-33 (always true). */    fun hasNotificationPermission(): Boolean}/** * Android [NotificationService] backed by [NotificationManager] + [NotificationManagerCompat]. */class AndroidNotificationService(    private val context: Context,    private val notificationManager: NotificationManager,) : NotificationService {    override fun ensureChannel(channelId: String, name: String, description: String, importance: Int) {        // Channel creation is a no-op on API < 26 (channels don't exist).        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return        // Idempotent: skip if channel already exists.        if (notificationManager.getNotificationChannel(channelId) != null) return        try {            val channel = NotificationChannel(channelId, name, importance).apply {                this.description = description            }            notificationManager.createNotificationChannel(channel)        } catch (t: Throwable) {            Timber.tag("AndroidNotificationService").w("ensureChannel failed for $channelId", t)        }    }    override fun channelExists(channelId: String): Boolean {        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.O) return true  // channels don't exist pre-Oreo        return try {            notificationManager.getNotificationChannel(channelId) != null        } catch (t: Throwable) {            false        }    }    override fun postNotification(        id: Int,        channelId: String,        title: String,        text: String,        smallIconResId: Int,    ): Boolean {        if (!hasNotificationPermission()) {            Timber.tag("AndroidNotificationService").w("POST_NOTIFICATIONS not granted")            return false        }        return try {            val builder = NotificationCompat.Builder(context, channelId)                .setSmallIcon(smallIconResId)                .setContentTitle(title)                .setContentText(text)                .setStyle(NotificationCompat.BigTextStyle().bigText(text))                .setAutoCancel(true)            NotificationManagerCompat.from(context).notify(id, builder.build())            true        } catch (e: SecurityException) {            Timber.tag("AndroidNotificationService").w("SecurityException posting notification", e)            false        } catch (t: Throwable) {            Timber.tag("AndroidNotificationService").w("postNotification failed", t)            false        }    }    override fun cancelNotification(id: Int) {        try {            notificationManager.cancel(id)        } catch (t: Throwable) {            Timber.tag("AndroidNotificationService").w("cancelNotification failed for $id", t)        }    }    override fun cancelAll() {        try {            notificationManager.cancelAll()        } catch (t: Throwable) {            Timber.tag("AndroidNotificationService").w("cancelAll failed", t)        }    }    override fun hasNotificationPermission(): Boolean {        // API 33+ requires POST_NOTIFICATIONS runtime permission.        if (Build.VERSION.SDK_INT < Build.VERSION_CODES.TIRAMISU) return true        return try {            context.checkSelfPermission(android.Manifest.permission.POST_NOTIFICATIONS) ==                android.content.pm.PackageManager.PERMISSION_GRANTED        } catch (t: Throwable) {            false        }    }}